import java.util.Scanner;

public class Main {
    public static void countDown(int n) {
        if (n == 0) {
            System.out.println("到站喵");
            return;
        }
        System.out.println("往下 " + n);
        countDown(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        countDown(n);
    }
}

