import java.util.Scanner;

public class Main {
    public static long fact(int n) {
        if (n == 0) {
            return 1;
        }
        return n * fact(n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        System.out.println("本喵算好了喵");
        System.out.println(n + " 的阶乘是 " + fact(n));
    }
}

